        const orgDetails = this.$store.getters.GetOrgDetails;
        const key = ["quotations", orgDetails.organization.organization_id, `${Date.now()}__${this.orderForm.imageFile.name.replace(/\s+/g, "")}`].join("/");
        const fileUrl = await uploadToS3(this.orderForm.imageFile, orgDetails.s3_details, key);
        if (fileUrl) {
          this.bucketUrls.image = fileUrl;
